public class TaskProcessor
{
    public void ProcessBatch(List<Action> tasks)
    {
        foreach (var task in tasks)
        {
            ThreadPool.QueueUserWorkItem(_ => task());
        }
    }

    public async Task ProcessBatchAsync(List<Func<CancellationToken, Task>> tasks)
    {
        var options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
        await Task.WhenAll(tasks.Select(t => t(CancellationToken.None)));
    }
}
